import React, {FC} from 'react';
import './CatalogItems.scss';
import SortMenu from "../../entities/SortMenu/SortMenu";
import CountPrice from "../../common/CountPrice/CountPrice";
import FilterMenu from "../../entities/FilterMenu/FilterMenu";
import {IReminder} from "../../../interfaces/reminderInterfaces";
import Reminder from "../../entities/Reminder/Reminder";

const reminders: IReminder[] = [
    {
        id: 1,
        title: 'Call mom',
        description: 'Call mom and wish her a happy birthday',
        price: 0,
        dueDate: 'Oct 25 2024, 11:15 PM',
        lastUpdated: 'Oct 25 2024, 11:15 PM',
    },
    {
        id: 2,
        title: 'Buy groceries',
        description: 'Buy groceries for the week',
        price: 0,
        dueDate: 'Oct 26 2024, 11:15 PM',
        lastUpdated: 'Oct 26 2024, 11:15 PM',
    },
    {
        id: 3,
        title: 'Send report',
        description: 'Send the report to the manager',
        price: 0,
        dueDate: 'Oct 27 2024, 11:15 PM',
        lastUpdated: 'Oct 27 2024, 11:15 PM',
    },
    {
        id: 4,
        title: 'Go to the gym',
        description: 'Go to the gym and work out',
        price: 0,
        dueDate: 'Oct 28 2024, 11:15 PM',
        lastUpdated: 'Oct 28 2024, 11:15 PM',
    }
]

interface SectionItemsProps {
    doctors: IReminder[];
    setDoctors: Dispatch<React.SetStateAction<IDoctor[]>>;
    searchOptions: {term: string, sort: string};
    setSearchOptions: Dispatch<React.SetStateAction<{term: string, sort: string}>>;

}

const CatalogItems: FC = () => {
    return (
        <section className={"main-container"}>
            <div className={'menu'}>
                <SortMenu/>
                <hr/>
                <FilterMenu/>
                <hr/>
                <CountPrice/>
            </div>
            <div className={"reminders-container"} id="reminders-container">
                {reminders.map((value, key) => (
                    <Reminder key={key} reminder={value} onDelete={() => {console.log('delete')}} onUpdateModal={() => {}} />
                ))}
            </div>
        </section>
    );
};

export default CatalogItems;
